This finally fixes the confusing error messages you get when you forget a parameter and it starts complaining about type mismatches:
```zig
const S = struct {
    a: u32,
    fn foo(_: *S, _: u32, _: bool) void {}
};
pub export fn entry() void {
    var s: S = undefined;
    s.foo(true);
}
// stage1:
// ./a.zig:7:11: error: expected type 'u32', found 'bool'
//     s.foo(true);
//           ^
// this branch:
// a.zig:7:10: error: member function expected 2 argument(s), found 1
//     s.foo(true);
//     ~~~~~^~~~~~
```

Also closes #1708 for stage2.
